    "h|(~A + B + C).(~A + ~B) = ~A + (B + C).~B = ~A + ~B.C.": "(~A + B + C).(~A + ~B) = ~A + (B + C).~B = ~A + ~B.C.",
    "h|X : la colonne CD = 00 et la colonne CD = 10 sont pleines.": "X: column CD = 00 and column CD = 10 are full.",
